style.css:
/* ВСЕ ТЕКСТЫ ГОЛУБЫЕ */
* {
  color: #7fd7ff !important;
  font-family: "Inter", "Segoe UI", sans-serif !important;
}

/* ТЁМНО-ГОЛУБОЙ ФОН */
body {
  background-color: #0a1e33 !important;
  background-image: radial-gradient(circle at top, #0d2a4d, #0a1e33 70%) !important;
}

/* Ссылки */
a {
  color: #6fd3ff !important;
  text-decoration: underline !important;
}

/* Кнопки и поля ввода */
button, input, select, textarea {
  background-color: rgba(20, 50, 80, 0.85) !important;
  color: #7fd7ff !important;
  border: 1px solid #4fc3ff !important;
  border-radius: 8px !important;
}

/* Прозрачные блоки */
div, section, article, main {
  background: rgba(10, 25, 45, 0.8) !important;
  border-radius: 6px !important;
}
